:root {
  --color-bg: #f0e6d2;
  --color-card: #fff8ee;
  --color-primary: #6b4f3a;
  --color-accent: #e8a87c;
  --color-hunger: #e07a5f;
  --color-happiness: #f2cc8f;
  --color-energy: #81b29a;
  --color-text: #3d2c1e;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --spacing: 1rem;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--color-text);
  padding: var(--spacing);
}

.card {
  background: var(--color-card);
  border-radius: var(--radius);
  padding: calc(var(--spacing) * 2);
  max-width: 420px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: var(--spacing);
  color: var(--color-primary);
}

/* Pixel Pet CSS */
.pet-container {
  display: flex;
  justify-content: center;
  margin-bottom: var(--spacing);
}

.pet {
  position: relative;
  width: 120px;
  height: 120px;
  image-rendering: pixelated;
}

.pet-body {
  position: absolute;
  width: 80px;
  height: 80px;
  background: var(--color-accent);
  border-radius: 12px;
  bottom: 0;
  left: 20px;
  box-shadow: 0 4px 0 var(--color-primary);
}

.pet-eye {
  position: absolute;
  width: 12px;
  height: 12px;
  background: var(--color-primary);
  border-radius: 50%;
  top: 24px;
}

.pet-eye.left { left: 16px; }
.pet-eye.right { right: 16px; }

.pet-mouth {
  position: absolute;
  width: 20px;
  height: 6px;
  background: var(--color-primary);
  border-radius: 0 0 10px 10px;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
}

.pet-ear {
  position: absolute;
  width: 24px;
  height: 24px;
  background: var(--color-accent);
  border-radius: 50% 50% 0 0;
  top: 8px;
}

.pet-ear.left { left: 12px; transform: rotate(-20deg); }
.pet-ear.right { right: 12px; transform: rotate(20deg); }

.pet-tail {
  position: absolute;
  width: 16px;
  height: 40px;
  background: var(--color-accent);
  border-radius: 8px;
  bottom: 10px;
  right: -8px;
  transform: rotate(30deg);
}

/* Mood text */
.mood {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--spacing);
  color: var(--color-primary);
}

/* Bars */
.bars {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: calc(var(--spacing) * 1.5);
}

.bar-group {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
}

.bar-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-primary);
}

.bar {
  width: 100%;
  height: 16px;
  background: #e0d5c8;
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: var(--color-hunger); }
.bar-fill.happiness { background: var(--color-happiness); }
.bar-fill.energy { background: var(--color-energy); }

/* Controls */
.controls {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: var(--radius);
  background: var(--color-primary);
  color: var(--color-card);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: var(--color-accent);
  color: var(--color-primary);
}

button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.95);
}

/* Responsive */
@media (max-width: 400px) {
  .card { padding: var(--spacing); }
  h1 { font-size: 1.5rem; }
  button { padding: 0.6rem 1rem; font-size: 0.9rem; }
}

// State
const state = {
  hunger: 80,
  happiness: 70,
  energy: 60
};

// DOM elements
const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const hungerFill = hungerBar.querySelector('.bar-fill');
const happinessFill = happinessBar.querySelector('.bar-fill');
const energyFill = energyBar.querySelector('.bar-fill');

// Clamp values between 0 and 100
function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

// Update UI from state
function updateUI() {
  hungerFill.style.width = state.hunger + '%';
  happinessFill.style.width = state.happiness + '%';
  energyFill.style.width = state.energy + '%';

  hungerBar.setAttribute('aria-valuenow', state.hunger);
  happinessBar.setAttribute('aria-valuenow', state.happiness);
  energyBar.setAttribute('aria-valuenow', state.energy);

  // Determine mood based on average stats
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood = 'Happy';
  if (avg < 30) mood = 'Sad';
  else if (avg < 60) mood = 'Okay';
  else if (avg < 85) mood = 'Happy';
  else mood = 'Ecstatic';
  moodEl.textContent = 'Mood: ' + mood;
}

// Actions
function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 25);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

// Event listeners
const feedBtn = document.getElementById('feed-btn');
const playBtn = document.getElementById('play-btn');
const sleepBtn = document.getElementById('sleep-btn');

feedBtn.addEventListener('click', feed);
playBtn.addEventListener('click', play);
sleepBtn.addEventListener('click', sleep);

// Initial render
updateUI();
